#!/bin/bash
# Generates /opt/app/load-ssm-env.sh from VAR=/ssm/path pairs. Alpine
# equivalent of assets/ec2/setup-ssm-env.sh: reads via ctech-ec2-agent
# ssm-get instead of the AWS CLI, same read-at-start contract.
#
# KMS policy: a SecureString is decrypted once per change, not once per read.
# The generated file is sourced by every cron job (billing `deliver` runs every
# minute), so the decrypted value is cached on tmpfs (/run, RAM only, 0600) keyed
# by the hash of the ciphertext (`ssm-get -decrypt=false`: no KMS call, changes
# on rotation). Needs nothing newer than the agent baked into the AMI.
#
# Usage: setup-ssm-env.sh VAR=/ssm/path [VAR=/ssm/path ...]
set -euo pipefail

OUT=/opt/app/load-ssm-env.sh

[ "$#" -gt 0 ] || { echo "setup-ssm-env.sh: at least one VAR=/ssm/path pair required" >&2; exit 1; }

for pair in "$@"; do
  case "$pair" in
    *=/*) ;;
    *) echo "setup-ssm-env.sh: expected VAR=/ssm/path, got '$pair'" >&2; exit 1 ;;
  esac
done

mkdir -p /opt/app
{
  echo '# Generated by setup-ssm-env.sh — do not edit.'
  cat << 'FN'
_ctech_ssm(){
  local dir=/run/ctech-ssm cache ct h val
  cache="$dir/$(printf %s "$1" | sha256sum | cut -d' ' -f1)"
  ct=$(ctech-ec2-agent ssm-get -decrypt=false -name "$1" 2>/dev/null) || { echo ""; return; }
  h=$(printf %s "$ct" | sha256sum | cut -d' ' -f1)
  if [ "$(head -n1 "$cache" 2>/dev/null)" = "$h" ]; then tail -n +2 "$cache"; return; fi
  val=$(ctech-ec2-agent ssm-get -name "$1" 2>/dev/null) || { echo ""; return; }
  ( umask 077; mkdir -p "$dir"; printf '%s\n%s' "$h" "$val" > "$cache.$$" && mv "$cache.$$" "$cache" ) 2>/dev/null || true
  printf '%s' "$val"
}
FN
  for pair in "$@"; do
    name="${pair%%=*}"
    ssm_path="${pair#*=}"
    printf '%s=$(_ctech_ssm %q)\n' "$name" "$ssm_path"
  done
} > "$OUT"
chmod 0644 "$OUT"
